    set_skill("damo-jian", 50);
    set_skill("buddhism", 50);
    set_skill("literate", 50);

    map_skill("force", "hunyuan-yiqi");
    map_skill("dodge", "shaolin-shenfa");
    map_skill("strike", "banruo-zhang");
    map_skill("sword", "damo-jian");
    map_skill("parry", "damo-jian");

    prepare_skill("strike", "banruo-zhang");

    create_family("少林派", 39, "弟子");

    set("inquiry", ([
        "铁护腕": (: ask_me_1, "huwan" :),
        "铁护腰": (: ask_me_1, "huyao" :),
        "皮手套": (: ask_me_1, "shoutao" :),
        "皮围脖": (: ask_me_1, "weibo" :),
        "铁指套": (: ask_me_1, "zhitao" :),
        "僧鞋": (: ask_me_1, "sengxie" :),
        "铁背心": (: ask_me_2, "beixin" :)
    ]));

    set("huju_count", 50);
    set("beixin_count", 5);

    setup();

    carry_object("/d/items/sword/changjian5")->wield();
    carry_object("/d/items/cloth/hui_jiasha")->wear();
}

string ask_me_1(string name) {
    mapping fam;
    object ob;

    if (!(fam = this_player()->query("family")) || fam["family_name"] != "少林派")
        return RANK_D->query_respect(this_player()) + "与本派素无来往，不知此话从何谈起？";

    if (present(name, this_player()))
        return RANK_D->query_respect(this_player()) + "你现在身上不是有这样防具吗，怎麽又来要了？ 真是贪得无餍！";

    if (query("huju_count") < 1)
        return "抱歉，你来得不是时候，防具已经发完了。";

    if (name == "huwan")
        ob = new("/d/items/wrists/shaolin_huwan");
    else if (name == "weibo")
        ob = new("/d/items/neck/shaolin_weibo");
    else if (name == "shoutao")
        ob = new("/d/items/hands/shaolin_shoutao");
    else if (name == "zhitao")
        ob = new("/d/items/hands/shaolin_zhitao");
    else if (name == "sengxie")
        ob = new("/d/items/boots/shaolin_sengxie");
    else
        ob = new("/d/shaolin/obj/" + name);
    ob->move(this_player());

    add("huju_count", -1);

    message_vision("道相给$N一件" + ob->query("name") + "。\n", this_player());

    return "拿去吧。不过要记住，防具只可防身练武，不可凭此妨害他人。";
}

string ask_me_2(string name) {
    mapping fam;
    object ob;

    if (!(fam = this_player()->query("family")) || fam["family_name"] != "少林派")
        return RANK_D->query_respect(this_player()) + "与本派素无来往，不知此话从何谈起？";

    if (query("beixin_count") < 1)
        return "抱歉，你来得不是时候，武器已经发完了。";

    ob = new("/d/items/cloth/tie_beixin2");
    ob->move(this_player());

    add("beixin_count", -1);

    message_vision("道相给$N一件" + ob->query("name") + "。\n", this_player());

    return "拿去吧。不过要记住，铁背心乃是防身宝物，不可凭此妨害他人。";
}

